window.AUTH=window.AUTH||{};window.AUTH["24-154"]={"d":"24-154","id":"2024/24-154","n":"Catholic Charities Bureau, Inc. v. Wisconsin Labor & Industry Review Commission","briefs":[{"k":"petitioner","label":"Brief of petitioners Catholic Charities Bureau, Inc., et al.","date":"2025-01-27","url":"https://www.supremecourt.gov/DocketPDF/24/24-154/340257/20250127183640202_CCB%20v%20WI%20Merits%20Brief%20FINAL.pdf","side":"pet","n":65},{"k":"united-states","label":"Brief amicus curiae of the United States","date":"2025-02-03","url":"https://www.supremecourt.gov/DocketPDF/24/24-154/341795/20250203145905438_24-154_tsacUnitedStates.pdf","side":"us","n":69},{"k":"respondent","label":"Brief of respondents Wisconsin Labor & Industry Review Commission, et al.","date":"2025-02-26","url":"https://www.supremecourt.gov/DocketPDF/24/24-154/348779/20250226160847325_24-154%20Brief%20for%20Respondent.pdf","side":"res","n":91},{"k":"reply","label":"Reply of petitioners Catholic Charities Bureau, Inc., et al.","date":"2025-03-21","url":"https://www.supremecourt.gov/DocketPDF/24/24-154/352693/20250321120813810_CCB%20Merits%20Reply%20Brief%20FINAL--final.pdf","side":"pet","n":34}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/605us1r37_986b.pdf","tr":true,"items":[{"t":"case","label":"American Legion v. American Humanist Ass’n","cite":"588 U.S. 29","y":2019,"id":"2018/17-1717","sc":1,"sum":"The Court held that the display and maintenance of a large memorial cross by a local government does not violate the Establishment Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Burwell v. Hobby Lobby Stores, Inc.","cite":"573 U.S. 682","y":2014,"id":"2013/13-354","sc":1,"sum":"The Court decided that the Affordable Care Act's requirement of for-profit corporations to supply its employees with contraceptives that go against the owners' beliefs is unconstitutional under the Religious Freedom Restoration Act of 1993.","sumSrc":"Oyez","by":{"0":"42","1":"19, 20"}},{"t":"case","label":"California v. Grace Brethren Church","cite":"457 U.S. 393","y":1982,"id":"1981/81-31","sc":1,"sum":"The Federal Unemployment Tax Act established a cooperative federalstate scheme to provide benefits to unemployed workers. The Act requires employers to pay an excise tax on wages paid to employees in \"covered\" employment, but entitles them to a credit on the federal tax for contributions paid into federally approved state unemployment compensation programs. The Act, in 26 U. S. C. § 3309(b), exempts from mandatory …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6","2":"6"}},{"t":"case","label":"Cantwell v. Connecticut","cite":"310 U.S. 296","y":1940,"id":"1940-1955/310us296","sc":1,"sum":"The Court found that it was a violation of the First Amendment to restrict solicitation of religious speech.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Carson v. Makin","cite":"596 U.S. 767","y":2022,"id":"2021/20-1088","sc":1,"op":1,"sum":"Maine’s “nonsectarian” requirement for otherwise generally available tuition assistance payments to parents who live in school districts that do not operate a secondary school of their own violates the Free Exercise Clause of the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"20, 22, 35, 39, 43-44","1":"27, 30","2":"42, 43","3":"4, 6, 19, 23"}},{"t":"case","label":"Church of Lukumi Babalu Aye, Inc. v. City of Hialeah","cite":"508 U.S. 520","y":1993,"id":"1992/91-948","sc":1,"sum":"The Court found that an ordinance banning religious animal sacrifice was unconstitutional under the Free Exercise Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"18, 20, 43, 44","2":"38, 41","3":"6, 17"}},{"t":"case","label":"45, 48, 49 Colorado Christian Univ. v. Weaver","cite":"534 F.3d 1245","y":2008,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/534/1245/","by":{"0":"34","3":"18-19"}},{"t":"case","label":"Corporation of Presiding Bishop v. Amos","cite":"483 U.S. 327","y":1987,"id":"1986/86-179","sc":1,"sum":"To be valid, the state action must first promote a \"secular legislative purpose.\" The Court found that Section 702 satisfied this criterion, since it ensured that the government would not determine for religious organizations what they could count as religious activities.","sumSrc":"Oyez","by":{"0":"36, 39","1":"28, 39","2":"16, 17, 20, 29, 33","3":"16"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"ar":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"0":"42, 45","1":"19, 34","3":"11, 18"}},{"t":"case","label":"vii Employment Div. v. Smith","cite":"494 U.S. 872","y":1990,"id":"1989/88-1213","sc":1,"op":1,"sum":"The Court held that the First Amendment does not protect individuals engaging in illegal acts as part of a religious ceremony.","sumSrc":"Oyez","by":{"0":"20, 43","2":"38"}},{"t":"case","label":"Espinoza v. Montana Dep’t of Revenue","cite":"591 U.S. 464","y":2020,"id":"2019/18-1195","sc":1,"op":1,"sum":"The Court held a Montana state law that provides funding for education but excludes religious education options violates the Free Exercise Clause of the federal Constitution.","sumSrc":"Oyez","by":{"0":"23","3":"5, 6, 23"}},{"t":"case","label":"Everson v. Board of Educ.","cite":"330 U.S. 1","y":1947,"id":"1940-1955/330us1","sc":1,"sum":"The Court held that a New Jersey law granting the parents of both public and Catholic school students reimbursements for riding public transportation did not violate the First Amendment.","sumSrc":"Oyez","by":{"0":"19, 34, 43","2":"35"}},{"t":"case","label":"Falwell v. Miller","cite":"203 F. Supp. 2d 624","y":2002,"court":"W.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/203/624/","by":{"0":"26"}},{"t":"case","label":"Fellowship of Christian Athletes v. San Jose Unified Sch. Dist. Bd. of Educ.","cite":"82 F.4th 664","y":2023,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/82/664/","by":{"0":"23-24"}},{"t":"case","label":"Fowler v. Rhode Island","cite":"345 U.S. 67","y":1953,"id":"scdb/1952-057","sc":1,"op":1,"sum":"A municipal ordinance which is so construed and applied as to penalize a minister of Jehovah's Witnesses for preaching at a peaceful religious meeting in a public park, although other religious groups could conduct religious services there with impunity, violates the First and Fourteenth Amendments of the Federal Constitution. Pp. 67-70. 80 R. I.-, 91 A. 2d 27, reversed. Appellant's conviction for violation of a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 37, 45","2":"32","3":"12, 18"}},{"t":"case","label":"Fulton v. City of Philadelphia","cite":"593 U.S. 522","y":2021,"id":"2020/19-123","sc":1,"sum":"Philadelphia’s refusal to contract with Catholic Social Services for the provision of foster care services unless CSS agrees to certify same-sex couples as foster parents violates the Free Exercise Clause of the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"20, 48","1":"28","2":"39, 40","3":"21"}},{"t":"case","label":"Gonzales v. O Centro Espírita Beneficente União do Vegetal","cite":"546 U.S. 418","y":2006,"id":"2005/04-1084","sc":1,"sum":"In a unanimous 8-0 decision (Justice Alito not participating), the Court held that the government had failed to prove a compelling interest in regulating the UDV's use of drugs for religious purposes. Writing for the Court, Chief Justice John Roberts rejected the government's argument that the Controlled Substances Act could accommodate no exceptions.","sumSrc":"Oyez","by":{"0":"49","1":"23","3":"11, 21"}},{"t":"case","label":"Gonzalez v. Roman Catholic Archbishop of Manila","cite":"280 U.S. 1","y":1929,"id":"scdb/1929-001","sc":1,"sum":"1. A judgment of the Supreme Court of the Ph,ippine Islands in a case in which the amount in controversy exccedA $25,000, is reviewable by this Court on certiorari.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 24"}},{"t":"case","label":"Holt v. Hobbs","cite":"574 U.S. 352","y":2015,"id":"2014/13-6827","sc":1,"sum":"The Court held that the Department of Corrections' grooming policy violated an inmate's right to religious exercise.","sumSrc":"Oyez","by":{"0":"41-42, 49","1":"22","2":"32"}},{"t":"case","label":"Hope Cmty. Church v. Warner","cite":"2024 WL 4310866","y":2024,"court":"N.D. W.Va. Sept. 26","by":{"0":"26"}},{"t":"case","label":"viii Hosanna-Tabor Evangelical Lutheran Church & Sch. v. EEOC","cite":"565 U.S. 171","y":2012,"id":"2011/10-553","sc":1,"op":4,"ar":2,"sum":"The Court found that a woman employed by a religious school who taught daily religion classes, was a commissioned minister, and regularly lead students in prayer and worship, did not have grounds to sue the school under the Ministerial Exception.","sumSrc":"Oyez","by":{"0":"20, 21, 24, 30, 31, 37","1":"27","2":"2, 18, 24, 25, 26, 30, 31, 49, 50, 53","3":"3-4, 13, 15"}},{"t":"case","label":"Kedroff v. Saint Nicholas Cathedral of Russian Orthodox Church in N. Am.","cite":"344 U.S. 94","y":1952,"id":"scdb/1952-013","sc":1,"op":3,"sum":"As thus construed and applied, the New York statute interferes with the free exercise of religion, contrary to the-First Amendment, made applicable to the states by the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 24, 27, 30","1":"27","3":"3, 4"}},{"t":"case","label":"Kendall v. Director of Div. of Emp. Sec.","cite":"473 N.E.2d 196","y":1985,"url":"https://www.courtlistener.com/c/N.E.2d/473/196/","by":{"0":"42","2":"61","3":"10"}},{"t":"case","label":"Kennedy v. Bremerton Sch. Dist.","cite":"597 U.S. 507","y":2022,"id":"2021/21-418","sc":1,"sum":"The Free Exercise and Free Speech Clauses of the First Amendment protect an individual engaging in a personal religious observance from government reprisal; the Constitution neither mandates nor permits the government to suppress such religious expression.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"19, 20-21"}},{"t":"case","label":"Korte v. Sebelius","cite":"735 F.3d 654","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/735/654/","by":{"0":"42"}},{"t":"case","label":"Kreshik v. Saint Nicholas Cathedral","cite":"363 U.S. 190","y":1960,"id":"1959/824","sc":1,"sum":"Certiorari is granted and a decision of the Court of Appeals of New York, holding that, under the common law of New York, petitioners, as the appointees of the Patriarch of Moscow., may not exercise the right -conferred under canon law to use and occupy St. Nicholas Cathedral of the Russian Orthodox Church in New York City, is reversed on the authority of Kedroff v. St. Nicholas Cathedral, 344 U. S. 94, since the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Larson v. Valente","cite":"456 U.S. 228","y":1982,"id":"1981/80-1666","sc":1,"op":8,"ar":8,"sum":"The Court held that the fifty percent rule clearly distinguished between denominations and created denominational preferences within the law, and it did not serve a compelling government interest. The Court also held that the Act failed the three-part test established in Lemon v. Kurtzman by fostering the government entanglement in religion.","sumSrc":"Oyez","by":{"0":"18, 21, 22, 43-44, 47","1":"27, 30","2":"42","3":"4, 17, 18, 19"}},{"t":"case","label":"Little Sisters of the Poor Saints Peter & Paul Home v. Pennsylvania","cite":"591 U.S. 657","y":2020,"id":"2019/19-431","sc":1,"op":1,"sum":"The Court held that the federal government acted properly when it added extensive exemptions to regulations requiring employers to include contraceptive coverage in employee health plans.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Mitchell v. Helms","cite":"530 U.S. 793","y":2000,"id":"1999/98-1648","sc":1,"sum":"In a 6-3 plurality decision delivered by Justice Clarence Thomas, the Court held that that Chapter 2, as applied in Jefferson Parish, is not a law respecting an establishment of religion simply because many of the private schools receiving Chapter 2 aid in the parish are religiously affiliated.","sumSrc":"Oyez","by":{"0":"34, 39","2":"20–21"}},{"t":"case","label":"Murphy v. Collier","cite":"139 S. Ct. 1475","y":2019,"url":"https://www.courtlistener.com/c/S.%20Ct./139/1475/","sc":1,"by":{"0":"22"}},{"t":"case","label":"ix New York v. Cathedral Acad.","cite":"434 U.S. 125","y":1977,"id":"1977/76-616","sc":1,"op":2,"sum":"A three-judge District Court issued a judgment (later affirmed by this Court) declaring unconstitutional a New York statute (1970 N. Y. Laws, ch. 138) that authorized reimbursement to nonpublic schools for statemandated recordkeeping and testing services, and permanently enjoinmg any payments under the Act, including reimbursement for expenses that such schools had already incurred in the last half of the 1971-1972 …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33-34, 39","1":"3, 28","2":"19, 20, 29"}},{"t":"case","label":"Niemotko v. Maryland","cite":"340 U.S. 268","y":1951,"id":"scdb/1950-024","sc":1,"sum":"Appellants were denied equal protection of the laws, in the exercise of freedom of speech and religion, contrary to the First and Fourteenth Amendments.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45","2":"39, 42"}},{"t":"case","label":"NLRB v. Catholic Bishop","cite":"440 U.S. 490","y":1979,"id":"1978/77-752","sc":1,"sum":"Schools operated by a church to teach both religious and secular subjects are not within the jurisdiction granted by the National Labor Relations Act, and the NLRB was therefore without authority to issue the orders against respondents.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 35-36, 37","1":"32","2":"19"}},{"t":"case","label":"Our Lady of Guadalupe Sch. v. Morrissey-Berru","cite":"591 U.S. 732","y":2020,"id":"2019/19-267","sc":1,"op":3,"sum":"The Court held that the First Amendment’s religion clauses prevent civil courts from adjudicating employment-discrimination claims brought by an employee against her religious employer, when the employee carried out important religious functions.","sumSrc":"Oyez","by":{"0":"18, 21, 24, 30-31","1":"20, 21, 26, 31, 32","2":"1, 2, 15, 17, 18, 19, 21, 22, 24, 25, 30, 45, 48, 49, 52, 53"}},{"t":"case","label":"35, 37 Patton v. United States","cite":"281 U.S. 276","y":1930,"id":"scdb/1929-043","sc":1,"sum":"1. After the commencement of a trial in a federal court before a jury of twelve men upon an indictment charging a crime, punishment for which may involve a penitentiary sentence, if one juror becomes incapacitated and unable to proceed further with his work as a juror, the defendant and the Government, through its official representative in charge of the case, may consent to the trial's proceeding to a finality with …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19-20"}},{"t":"case","label":"Presbyterian Church in U.S. v. Mary Elizabeth Blue Hull Mem’l Presbyterian Church","cite":"393 U.S. 440","y":1969,"id":"1968/71","sc":1,"op":1,"sum":"The Court held that the civil courts do not have the ability to determine title to church property on the basis of the civil court’s interpretation of the church doctrine.","sumSrc":"Oyez","by":{"0":"24","3":"10"}},{"t":"case","label":"Reed v. Town of Gilbert","cite":"576 U.S. 155","y":2015,"id":"2014/13-502","sc":1,"op":1,"sum":"The Court decided that extra restrictions placed on signs describing the location of nonprofit events do not survive strict scrutiny and are therefore unconstitutional.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Roman Catholic Diocese of Brooklyn v. Cuomo","cite":"592 U.S. 14","y":2020,"id":"2020/20a87","sc":1,"sum":"Respondent is enjoined from enforcing Executive Order 202.68’s 10- and 25-person occupancy limits on Applicant pending disposition of the appeal in the United States Court of Appeals for the Second Circuit and disposition of the petition for a writ of certiorari, if such writ is timely sought.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"45","2":"42"}},{"t":"case","label":"Serbian E. Orthodox Diocese for U.S. of Am. & Can. v. Milivojevich","cite":"426 U.S. 696","y":1976,"id":"1975/75-292","sc":1,"op":2,"ar":1,"sum":"During the course of a protracted dispute over the control of the Serbian Eastern Orthodox Diocese for the United States and Canada, the Holy Assembly of Bishops and the Holy Synod of the Serbian Orthodox Church (Mother Church) suspended and ultimately removed and defrocked the Bishop, respondent Dionisije, and appointed petitioner Firmilian as Administrator of the Diocese, which the Mother Church then reorganized …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 24-25, 28, 29-30","1":"27","2":"48, 49, 50","3":"3"}},{"t":"case","label":"Sherbert v. Verner","cite":"374 U.S. 398","y":1963,"id":"1962/526","sc":1,"sum":"The Court found that the denial of unemployment compensation because of religious practices violated the First and Fourteenth Amendments.","sumSrc":"Oyez","by":{"0":"45","2":"38, 39","3":"6, 18"}},{"t":"case","label":"x St. Martin Evangelical Lutheran Church v. South Dakota","cite":"451 U.S. 772","y":1981,"id":"1980/80-120","sc":1,"op":2,"sum":"Petitioners are exempt from unemployment compensation taxes under § 3309 (b) (1) (A).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 5, 6","1":"10, 12, 13, 24, 27, 33","2":"50, 51, 54, 56, 57","3":"11"}},{"t":"case","label":"Tandon v. Newsom","cite":"593 U.S. 61","y":2021,"url":"https://supreme.justia.com/cases/federal/us/593/61/","sc":1,"by":{"0":"20, 44, 45","2":"42"}},{"t":"case","label":"Thomas v. Review Bd.","cite":"450 U.S. 707","y":1981,"id":"1980/79-952","sc":1,"sum":"The Court held that the Review Board's denial of unemployment benefits to Thomas violated his First Amendment right to the free exercise of religion.","sumSrc":"Oyez","by":{"0":"18, 20, 36","1":"28","2":"32"}},{"t":"case","label":"Town of Greece v. Galloway","cite":"572 U.S. 565","y":2014,"id":"2013/12-696","sc":1,"sum":"The Court ruled that the invocation of prayer at a legislative session does not violate the Establishment Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Trinity Lutheran Church of Columbia, Inc. v. Comer","cite":"582 U.S. 449","y":2017,"id":"2016/15-577","sc":1,"op":1,"ar":1,"sum":"The Court determined that the exclusion of churches from an otherwise neutral and secular aid program violates the First Amendment’s guarantee of free exercise of religion.","sumSrc":"Oyez","by":{"0":"22, 23","3":"5, 6"}},{"t":"case","label":"United States v. Dykema","cite":"666 F.2d 1096","y":1981,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/666/1096/","op":2,"ar":3,"by":{"0":"14-15","1":"18, 19","2":"59"}},{"t":"case","label":"United States v. Quaintance","cite":"608 F.3d 717","y":2010,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/608/717/","by":{"0":"42"}},{"t":"case","label":"Universidad Cent. de Bayamon v. NLRB","cite":"793 F.2d 383","y":1985,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/793/383/","by":{"0":"35"}},{"t":"case","label":"University of Great Falls v. NLRB","cite":"278 F.3d 1335","y":2002,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/278/1335/","by":{"0":"36","1":"28"}},{"t":"case","label":"Walz v. Tax Comm’n of N.Y.","cite":"397 U.S. 664","y":1970,"id":"1969/135","sc":1,"ar":1,"sum":"In a 7-to-1 decision, the Court held that the exemptions did not violate the Establishment Clause. The Court held that the purpose of the exemptions was to neither advance nor inhibit religion; no one particular church or religious group had been singled out to receive tax exempt status.","sumSrc":"Oyez","by":{"0":"17-18, 33, 41","2":"15, 17, 19, 21, 28–29, 33"}},{"t":"case","label":"xi Widmar v. Vincent","cite":"454 U.S. 263","y":1981,"id":"1981/80-689","sc":1,"sum":"Jr., the Court held that the university’s policy violated Cornerstone members’ First Amendment rights. He reasoned that when the university opened its facilities to student meetings, it created a public forum for those student groups; given no other justification, the university excluded Cornerstone based on the content of its members’ speech.","sumSrc":"Oyez","by":{"0":"34","2":"20, 29"}},{"t":"case","label":"Wimberly v. Labor & Indus. Rels. Comm’n of Mo.","cite":"479 U.S. 511","y":1987,"id":"1986/85-129","sc":1,"sum":"The Missouri statute is consistent with the federal statute. The plain import of § 3304(a)(12)'s language is that Congress intended only to prohibit States from singling out pregnancy for unfavorable treatment and not to mandate preferential treatment. This is confirmed by both the legislative history and the Labor Department's interpretation of the statute. The focus of the statutory language is on the State's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5","1":"3, 24"}},{"t":"case","label":"Wisconsin v. Yoder","cite":"406 U.S. 205","y":1972,"id":"1971/70-110","sc":1,"sum":"The Court held that the First Amendment prohibited the state of Wisconsin to require Amish children to attend public school beyond the eighth grade.","sumSrc":"Oyez","by":{"0":"20, 41, 49","1":"20, 31"}},{"t":"case","label":"Zorach v. Clauson","cite":"343 U.S. 306","y":1952,"id":"1940-1955/343us306","sc":1,"op":1,"sum":"In a 6-to-3 decision, the Court held that the \"released time\" program neither constituted the establishment of religion nor interfered with the free exercise of religion.","sumSrc":"Oyez","by":{"0":"43, 45","2":"35","3":"18"}},{"t":"usc","label":"26 U.S.C. § 107","url":"https://www.law.cornell.edu/uscode/text/26/107","stext":{"head":"§107. Rental value of parsonages","paras":[[0,"In the case of a minister of the gospel, gross income does not include—"],[1,"(1) the rental value of a home furnished to him as part of his compensation; or"],[1,"(2) the rental allowance paid to him as part of his compensation, to the extent used by him to rent or provide a home and to the extent such allowance does not exceed the fair rental value of the home, including furnishings and appurtenances such as a garage, plus the cost of utilities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/107?type=usc&year=mostrecent&link-type=html"},"head":"§107. Rental value of parsonages","tname":"Internal Revenue Code","by":{"0":"31, 32","2":"46–47"}},{"t":"usc","label":"26 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/26/501","subs":["(c)(3)"],"stext":{"head":"§501. Exemption from tax on corporations, certain trusts, etc.","paras":[[0,"(a) Exemption from taxation"],[0,"An organization described in subsection (c) or (d) or section 401(a) shall be exempt from taxation under this subtitle unless such exemption is denied under section 502 or 503."],[0,"(b) Tax on unrelated business income and certain other activities"],[0,"An organization exempt from taxation under subsection (a) shall be subject to tax to the extent provided in parts II, III, and VI of this subchapter, but (notwithstanding parts II, III, and VI of this subchapter) shall be considered an organization exempt from income taxes for the purpose of any law which refers to organizations exempt from income taxes."],[0,"(c) List of exempt organizations"],[0,"The following organizations are referred to in subsection (a):"],[1,"(1) Any corporation organized under Act of Congress which is an instrumentality of the United States but only if such corporation—"],[2,"(A) is exempt from Federal income taxes—"],[3,"(i) under such Act as amended and supplemented before July 18, 1984, or"],[3,"(ii) under this title without regard to any provision of law which is not contained in this title and which is not contained in a revenue Act, or"],[2,"(B) is described in subsection (l)."],[1,"(2) Corporations organized for the exclusive purpose of holding title to property, collecting income therefrom, and turning over the entire amount thereof, less expenses, to an organization which itself is exempt under this section. Rules similar to the rules of subparagraph (G) of paragraph (25) shall apply for purposes of this paragraph."],[1,"(3) Corporations, and any community chest, fund, or foundation, organized and operated exclusively for religious, charitable, scientific, testing for public safety, literary, or educational purposes, or to foster national or international amateur sports competition (but only if no part of its activities involve the provision of athletic facilities or equipment), or for the prevention of cruelty to children or animals, no part of the net earnings of which inures to the benefit of any private shareholder or individual, no substantial part of the activities of which is carrying on propaganda, or otherwise attempting, to influence legislation (except as otherwise provided in subsection (h)), and which does not participate in, or intervene in (including the publishing or distributing of statements), any political campaign on behalf of (or in opposition to) any candidate for public office."],[1,"(4)(A) Civic leagues or organizations not organized for profit but operated exclusively for the promotion of social welfare, or local associations of employees, the membership of which is limited to the employees of a designated person or persons in a particular municipality, and the net earnings of which are devoted exclusively to charitable, educational, or recreational purposes."],[1,"(B) Subparagraph (A) shall not apply to an entity unless no part of the net earnings of such entity inures to the benefit of any private shareholder or individual."],[1,"(5) Labor, agricultural, or horticultural organizations."],[1,"(6) Business leagues, chambers of commerce, real-estate boards, boards of trade, or professional football leagues (whether or not administering a pension fund for football players), not organized for profit and no part of the net earnings of which inures to the benefit of any private shareholder or individual."],[1,"(7) Clubs organized for pleasure, recreation, and other nonprofitable purposes, substantially all of the activities of which are for such purposes and no part of the net earnings of which inures to the benefit of any private shareholder."],[1,"(8) Fraternal beneficiary societies, orders, or associations—"],[2,"(A) operating under the lodge system or for the exclusive benefit of the members of a fraternity itself operating under the lodge system, and"],[2,"(B) providing for the payment of life, sick, accident, or other benefits to the members of such society, order, or association or their dependents."],[1,"(9) Voluntary employees' beneficiary associations providing for the payment of life, sick, accident, or other benefits to the members of such association or their dependents or designated beneficiaries, if no part of the net earnings of such association inures (other than through such payments) to the benefit of any private shareholder or individual. For purposes of providing for the payment of sick and accident benefits to members of such an association and their dependents, the term \"dependent\" shall include any individual who is a child (as defined in section 152(f)(1)) of a member who as of the end of the calendar year has not attained age 27."],[1,"(10) Domestic fraternal societies, orders, or associations, operating under the lodge system—"],[2,"(A) the net earnings of which are devoted exclusively to religious, charitable, scientific, literary, educational, and fraternal purposes, and"],[2,"(B) which do not provide for the payment of life, sick, accident, or other benefits."],[1,"(11) Teachers' retirement fund associations of a purely local character, if—"],[2,"(A) no part of their net earnings inures (other than through payment of retirement benefits) to the benefit of any private shareholder or individual, and"],[2,"(B) the income consists solely of amounts received from public taxation, amounts received from assessments on the teaching salaries of members, and income in respect of investments."],[1,"(12)(A) Benevolent life insurance associations of a purely local character, mutual ditch or irrigation companies, mutual or cooperative telephone companies, or like organizations; but only if 85 percent or more of the income consists of amounts collected from members for the sole purpose of meeting losses and expenses."],[1,"(B) In the case of a mutual or cooperative telephone company, subparagraph (A) shall be applied without taking into account any income received or accrued—"],[2,"(i) from a nonmember telephone company for the performance of communication services which involve members of the mutual or cooperative telephone company,"],[2,"(ii) from qualified pole rentals,"],[2,"(iii) from the sale of display listings in a directory furnished to the members of the mutual or cooperative telephone company, or"],[2,"(iv) from the prepayment of a loan under section 306A, 306B, or 311 1 of the Rural Electrification Act of 1936 (as in effect on January 1, 1987)."],[1,"(C) In the case of a mutual or cooperative electric company, subparagraph (A) shall be applied without taking into account any income received or accrued—"],[2,"(i) from qualified pole rentals, or"],[2,"(ii) from any provision or sale of electric energy transmission services or ancillary services if such services are provided on a nondiscriminatory open access basis under an open access transmission tariff approved or accepted by FERC or under an independent transmission provider agreement approved or accepted by FERC (other than income received or accrued directly or indirectly from a member),"],[2,"(iii) from the provision or sale of electric energy distribution services or ancillary services if such services are provided on a nondiscriminatory open access basis to distribute electric energy not owned by the mutual or electric cooperative company—"],[3,"(I) to end-users who are served by distribution facilities not owned by such company or any of its members (other than income received or accrued directly or indirectly from a member), or"],[3,"(II) generated by a generation facility not owned or leased by such company or any of its members and which is directly connected to distribution facilities owned by such company or any of its members (other than income received or accrued directly or indirectly from a member),"],[2,"(iv) from any nuclear decommissioning transaction, or"],[2,"(v) from any asset exchange or conversion transaction."],[1,"(D) For purposes of this paragraph, the term \"qualified pole rental\" means any rental of a pole (or other structure used to support wires) if such pole (or other structure)—"],[2,"(i) is used by the telephone or electric company to support one or more wires which are used by such company in providing telephone or electric services to its members, and"],[2,"(ii) is used pursuant to the rental to support one or more wires (in addition to the wires described in clause (i)) for use in connection with the transmission by wire of electricity or of telephone or other communications."],[1,"For purposes of the preceding sentence, the term \"rental\" includes any sale of the right to use the pole (or other structure)."],[1,"(E) For purposes of subparagraph (C)(ii), the term \"FERC\" means—"],[2,"(i) the Federal Energy Regulatory Commission, or"],[2,"(ii) in the case of any utility with respect to which all of the electricity generated, transmitted, or distributed by such utility is generated, transmitted, distributed, and consumed in the same State, the State agency of such State with the authority to regulate electric utilities."],[1,"(F) For purposes of subparagraph (C)(iv), the term \"nuclear decommissioning transaction\" means—"],[2,"(i) any transfer into a trust, fund, or instrument established to pay any nuclear decommissioning costs if the transfer is in connection with the transfer of the mutual or cooperative electric company's interest in a nuclear power plant or nuclear power plant unit,"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/501?type=usc&year=mostrecent&link-type=html"},"head":"§501. Exemption from tax on corporations, certain trusts, etc.","tname":"Internal Revenue Code","by":{"0":"5, 15","1":"5, 8, 11, 14, 17, 18, 21","2":"6, 11, 14, 55, 56, 57, 59, 62"}},{"t":"usc","label":"26 U.S.C. § 1402","url":"https://www.law.cornell.edu/uscode/text/26/1402","subs":["(e)(1)","(g)","(g)(1)","(c)(4)"],"stext":{"head":"§1402. Definitions","paras":[[0,"(a) Net earnings from self-employment"],[0,"The term \"net earnings from self-employment\" means the gross income derived by an individual from any trade or business carried on by such individual, less the deductions allowed by this subtitle which are attributable to such trade or business, plus his distributive share (whether or not distributed) of income or loss described in section 702(a)(8) from any trade or business carried on by a partnership of which he is a member; except that in computing such gross income and deductions and such distributive share of partnership ordinary income or loss—"],[1,"(1) there shall be excluded rentals from real estate and from personal property leased with the real estate (including such rentals paid in crop shares, and including payments under section 1233(a)(2) of the Food Security Act of 1985 (16 U.S.C. 3833(a)(2)) to individuals receiving benefits under section 202 or 223 of the Social Security Act) together with the deductions attributable thereto, unless such rentals are received in the course of a trade or business as a real estate dealer; except that the preceding provisions of this paragraph shall not apply to any income derived by the owner or tenant of land if (A) such income is derived under an arrangement, between the owner or tenant and another individual, which provides that such other individual shall produce agricultural or horticultural commodities (including livestock, bees, poultry, and fur-bearing animals and wildlife) on such land, and that there shall be material participation by the owner or tenant (as determined without regard to any activities of an agent of such owner or tenant) in the production or the management of the production of such agricultural or horticultural commodities, and (B) there is material participation by the owner or tenant (as determined without regard to any activities of an agent of such owner or tenant) with respect to any such agricultural or horticultural commodity;"],[1,"(2) there shall be excluded dividends on any share of stock, and interest on any bond, debenture, note, or certificate, or other evidence of indebtedness, issued with interest coupons or in registered form by any corporation (including one issued by a government or political subdivision thereof), unless such dividends and interest are received in the course of a trade or business as a dealer in stocks or securities;"],[1,"(3) there shall be excluded any gain or loss—"],[2,"(A) which is considered as gain or loss from the sale or exchange of a capital asset,"],[2,"(B) from the cutting of timber, or the disposal of timber, coal, or iron ore, if section 631 applies to such gain or loss, or"],[2,"(C) from the sale, exchange, involuntary conversion, or other disposition of property if such property is neither—"],[3,"(i) stock in trade or other property of a kind which would properly be includible in inventory if on hand at the close of the taxable year, nor"],[3,"(ii) property held primarily for sale to customers in the ordinary course of the trade or business;"],[1,"(4) the deduction for net operating losses provided in section 172 shall not be allowed;"],[1,"(5) if—"],[2,"(A) any of the income derived from a trade or business (other than a trade or business carried on by a partnership) is community income under community property laws applicable to such income, the gross income and deductions attributable to such trade or business shall be treated as the gross income and deductions of the spouse carrying on such trade or business or, if such trade or business is jointly operated, treated as the gross income and deductions of each spouse on the basis of their respective distributive share of the gross income and deductions; and"],[2,"(B) any portion of a partner's distributive share of the ordinary income or loss from a trade or business carried on by a partnership is community income or loss under the community property laws applicable to such share, all of such distributive share shall be included in computing the net earnings from self-employment of such partner, and no part of such share shall be taken into account in computing the net earnings from self-employment of the spouse of such partner;"],[1,"(6) a resident of Puerto Rico shall compute his net earnings from self-employment in the same manner as a citizen of the United States but without regard to section 933;"],[1,"(7) the deduction for personal exemptions provided in section 151 shall not be allowed;"],[1,"(8) an individual who is a duly ordained, commissioned, or licensed minister of a church or a member of a religious order shall compute his net earnings from self-employment derived from the performance of service described in subsection (c)(4) without regard to section 107 (relating to rental value of parsonages), section 119 (relating to meals and lodging furnished for the convenience of the employer), and section 911 (relating to citizens or residents of the United States living abroad), but shall not include in such net earnings from self-employment the rental value of any parsonage or any parsonage allowance (whether or not excludable under section 107) provided after the individual retires, or any other retirement benefit received by such individual from a church plan (as defined in section 414(e)) after the individual retires;"],[1,"(9) the exclusion from gross income provided by section 931 shall not apply;"],[1,"(10) there shall be excluded amounts received by a partner pursuant to a written plan of the partnership, which meets such requirements as are prescribed by the Secretary, and which provides for payments on account of retirement, on a periodic basis, to partners generally or to a class or classes of partners, such payments to continue at least until such partner's death, if—"],[2,"(A) such partner rendered no services with respect to any trade or business carried on by such partnership (or its successors) during the taxable year of such partnership (or its successors), ending within or with his taxable year, in which such amounts were received, and"],[2,"(B) no obligation exists (as of the close of the partnership's taxable year referred to in subparagraph (A)) from the other partners to such partner except with respect to retirement payments under such plan, and"],[2,"(C) such partner's share, if any, of the capital of the partnership has been paid to him in full before the close of the partnership's taxable year referred to in subparagraph (A);"],[1,"(11) the exclusion from gross income provided by section 911(a)(1) shall not apply;"],[1,"(12) in lieu of the deduction provided by section 164(f) (relating to deduction for one-half of self-employment taxes), there shall be allowed a deduction equal to the product of—"],[2,"(A) the taxpayer's net earnings from self-employment for the taxable year (determined without regard to this paragraph), and"],[2,"(B) one-half of the sum of the rates imposed by subsections (a) and (b) of section 1401 for such year (determined without regard to the rate imposed under paragraph (2) of section 1401(b));"],[1,"(13) there shall be excluded the distributive share of any item of income or loss of a limited partner, as such, other than guaranteed payments described in section 707(c) to that partner for services actually rendered to or on behalf of the partnership to the extent that those payments are established to be in the nature of remuneration for those services;"],[1,"(14) in the case of church employee income, the special rules of subsection (j)(1) shall apply;"],[1,"(15) in the case of a member of an Indian tribe, the special rules of section 7873 (relating to income derived by Indians from exercise of fishing rights) shall apply;"],[1,"(16) the deduction provided by section 199 1 shall not be allowed; and"],[1,"(17) notwithstanding the preceding provisions of this subsection, each spouse's share of income or loss from a qualified joint venture shall be taken into account as provided in section 761(f) in determining net earnings from self-employment of such spouse."],[0,"If the taxable year of a partner is different from that of the partnership, the distributive share which he is required to include in computing his net earnings from self-employment shall be based on the ordinary income or loss of the partnership for any taxable year of the partnership ending within or with his taxable year. In the case of any trade or business which is carried on by an individual or by a partnership and in which, if such trade or business were carried on exclusively by employees, the major portion of the services would constitute agricultural labor as defined in section 3121(g)—"],[1,"(i) in the case of an individual, if the gross income derived by him from such trade or business is not more than the upper limit, the net earnings from self-employment derived by him from such trade or business may, at his option, be deemed to be 662/3 percent of such gross income; or"],[1,"(ii) in the case of an individual, if the gross income derived by him from such trade or business is more than the upper limit and the net earnings from self-employment derived by him from such trade or business (computed under this subsection without regard to this sentence) are less than the lower limit, the net earnings from self-employment derived by him from such trade or business may, at his option, be deemed to be the lower limit; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/1402?type=usc&year=mostrecent&link-type=html"},"head":"§1402. Definitions","tname":"Internal Revenue Code","by":{"0":"31","2":"16, 46, 32, 16, 46, 46"}},{"t":"usc","label":"26 U.S.C. § 3301","url":"https://www.law.cornell.edu/uscode/text/26/3301","stext":{"head":"§3301. Rate of tax","paras":[[0,"There is hereby imposed on every employer (as defined in section 3306(a)) for each calendar year an excise tax, with respect to having individuals in his employ, equal to 6 percent of the total wages (as defined in section 3306(b)) paid by such employer during the calendar year with respect to employment (as defined in section 3306(c))."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/3301?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3301. Rate of tax","tname":"Internal Revenue Code","by":{"0":"4","1":"1, 3","2":"6"}},{"t":"usc","label":"26 U.S.C. § 3302","url":"https://www.law.cornell.edu/uscode/text/26/3302","stext":{"head":"§3302. Credits against tax","paras":[[0,"(a) Contributions to State unemployment funds"],[0,"(1) The taxpayer may, to the extent provided in this subsection and subsection (c), credit against the tax imposed by section 3301 the amount of contributions paid by him into an unemployment fund maintained during the taxable year under the unemployment compensation law of a State which is certified as provided in section 3304 for the 12-month period ending on October 31 of such year."],[0,"(2) The credit shall be permitted against the tax for the taxable year only for the amount of contributions paid with respect to such taxable year."],[0,"(3) The credit against the tax for any taxable year shall be permitted only for contributions paid on or before the last day upon which the taxpayer is required under section 6071 to file a return for such year; except that credit shall be permitted for contributions paid after such last day, but such credit shall not exceed 90 percent of the amount which would have been allowable as credit on account of such contributions had they been paid on or before such last day."],[0,"(4) Upon the payment of contributions into the unemployment fund of a State which are required under the unemployment compensation law of that State with respect to remuneration on the basis of which, prior to such payment into the proper fund, the taxpayer erroneously paid an amount as contributions under another unemployment compensation law, the payment into the proper fund shall, for purposes of credit against the tax, be deemed to have been made at the time of the erroneous payment. If, by reason of such other law, the taxpayer was entitled to cease paying contributions with respect to services subject to such other law, the payment into the proper fund shall, for purposes of credit against the tax, be deemed to have been made on the date the return for the taxable year was filed under section 6071."],[0,"(5) In the case of wages paid by the trustee of an estate under title 11 of the United States Code, if the failure to pay contributions on time was without fault by the trustee, paragraph (3) shall be applied by substituting \"100 percent\" for \"90 percent\"."],[0,"(b) Additional credit"],[0,"In addition to the credit allowed under subsection (a), a taxpayer may credit against the tax imposed by section 3301 for any taxable year an amount, with respect to the unemployment compensation law of each State certified as provided in section 3303 for the 12-month period ending on October 31 of such year, or with respect to any provisions thereof so certified, equal to the amount, if any, by which the contributions required to be paid by him with respect to the taxable year were less than the contributions such taxpayer would have been required to pay if throughout the taxable year he had been subject under such State law to the highest rate applied thereunder in such 12-month period to any person having individuals in his employ, or to a rate of 5.4 percent, whichever rate is lower."],[0,"(c) Limit on total credits"],[0,"(1) The total credits allowed to a taxpayer under this section shall not exceed 90 percent of the tax against which such credits are allowable."],[0,"(2) If an advance or advances have been made to the unemployment account of a State under title XII of the Social Security Act, then the total credits (after applying subsections (a) and (b) and paragraph (1) of this subsection) otherwise allowable under this section for the taxable year in the case of a taxpayer subject to the unemployment compensation law of such State shall be reduced—"],[1,"(A)(i) in the case of a taxable year beginning with the second consecutive January 1 as of the beginning of which there is a balance of such advances, by 5 percent of the tax imposed by section 3301 with respect to the wages paid by such taxpayer during such taxable year which are attributable to such State; and"],[1,"(ii) in the case of any succeeding taxable year beginning with a consecutive January 1 as of the beginning of which there is a balance of such advances, by an additional 5 percent, for each such succeeding taxable year, of the tax imposed by section 3301 with respect to the wages paid by such taxpayer during such taxable year which are attributable to such State;"],[1,"(B) in the case of a taxable year beginning with the third or fourth consecutive January 1 as of the beginning of which there is a balance of such advances, by the amount determined by multiplying the wages paid by such taxpayer during such taxable year which are attributable to such State by the percentage (if any), multiplied by a fraction, the numerator of which is the State's average annual wage in covered employment for the calendar year in which the determination is made and the denominator of which is the wage base under this chapter, by which—"],[2,"(i) 2.7 percent multiplied by a fraction, the numerator of which is the wage base under this chapter and the denominator of which is the estimated United States average annual wage in covered employment for the calendar year in which the determination is to be made, exceeds"],[2,"(ii) the average employer contribution rate for such State for the calendar year preceding such taxable year; and"],[1,"(C) in the case of a taxable year beginning with the fifth or any succeeding consecutive January 1 as of the beginning of which there is a balance of such advances, by the amount determined by multiplying the wages paid by such taxpayer during such taxable year which are attributable to such State by the percentage (if any) by which—"],[2,"(i) the 5-year benefit cost rate applicable to such State for such taxable year or (if higher) 2.7 percent, exceeds"],[2,"(ii) the average employer contribution rate for such State for the calendar year preceding such taxable year."],[0,"Subparagraph (C) shall not apply with respect to any taxable year to which it would otherwise apply (but subparagraph (B) shall apply to such taxable year) if the Secretary of Labor determines (on or before November 10 of such taxable year) that the State meets the requirements of subsection (f)(2)(B) for such taxable year."],[0,"(3) If the Secretary of Labor determines that a State, or State agency, has not—"],[1,"(A) entered into the agreement described in section 239 of the Trade Act of 1974, with the Secretary of Labor before July 15, 1975, or"],[1,"(B) fulfilled its commitments under an agreement with the Secretary of Labor as described in section 239 of the Trade Act of 1974,"],[0,"then, in the case of a taxpayer subject to the unemployment compensation law of such State, the total credits (after applying subsections (a) and (b) and paragraphs (1) and (2) of this section) otherwise allowable under this section for a year during which such State or agency does not enter into or fulfill such an agreement shall be reduced by 7½ percent of the tax imposed with respect to wages paid by such taxpayer during such year which are attributable to such State."],[0,"(d) Definitions and special rules relating to subsection (c)"],[0,"(1) Rate of tax deemed to be 6 percent"],[1,"In applying subsection (c), the tax imposed by section 3301 shall be computed at the rate of 6 percent in lieu of the rate provided by such section."],[0,"(2) Wages attributable to a particular State"],[1,"For purposes of subsection (c), wages shall be attributable to a particular State if they are subject to the unemployment compensation law of the State, or (if not subject to the unemployment compensation law of any State) if they are determined (under rules or regulations prescribed by the Secretary) to be attributable to such State."],[0,"(3) Additional taxes inapplicable where advances are repaid before November 10 of taxable year"],[1,"Paragraph (2) of subsection (c) shall not apply with respect to any State for the taxable year if (as of the beginning of November 10 of such year) there is no balance of advances referred to in such paragraph."],[0,"(4) Average employer contribution rate"],[1,"For purposes of subparagraphs (B) and (C) of subsection (c)(2), the average employer contribution rate for any State for any calendar year is that percentage obtained by dividing—"],[2,"(A) the total of the contributions paid into the State unemployment fund with respect to such calendar year, by"],[2,"(B)(i) for purposes of subparagraph (B) of subsection (c)(2), the total of the wages (as determined without any limitation on amount) attributable to such State subject to contributions under this chapter with respect to such calendar year, and"],[2,"(ii) for purposes of subparagraph (C) of subsection (c)(2), the total of the remuneration subject to contributions under the State unemployment compensation law with respect to such calendar year."],[1,"For purposes of subparagraph (C) of subsection (c)(2), if the average employer contribution rate for any State for any calendar year (determined without regard to this sentence) equals or exceeds 2.7 percent, such rate shall be determined by increasing the amount taken into account under subparagraph (A) of the preceding sentence by the aggregate amount of employee payments (if any) into the unemployment fund of such State with respect to such calendar year which are to be used solely in the payment of unemployment compensation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/3302?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3302. Credits against tax","tname":"Internal Revenue Code","by":{"0":"5","1":"3"}},{"t":"usc","label":"26 U.S.C. § 3304","url":"https://www.law.cornell.edu/uscode/text/26/3304","subs":["(c)"],"stext":{"head":"§3304. Approval of State laws","paras":[[0,"(a) Requirements"],[0,"The Secretary of Labor shall approve any State law submitted to him, within 30 days of such submission, which he finds provides that—"],[1,"(1) all compensation is to be paid through public employment offices or such other agencies as the Secretary of Labor may approve;"],[1,"(2) no compensation shall be payable with respect to any day of unemployment occurring within 2 years after the first day of the first period with respect to which contributions are required;"],[1,"(3) all money received in the unemployment fund shall (except for refunds of sums erroneously paid into such fund and except for refunds paid in accordance with the provisions of section 3305(b)) immediately upon such receipt be paid over to the Secretary of the Treasury to the credit of the Unemployment Trust Fund established by section 904 of the Social Security Act (42 U.S.C. 1104);"],[1,"(4) all money withdrawn from the unemployment fund of the State shall be used solely in the payment of unemployment compensation, exclusive of expenses of administration, and for refunds of sums erroneously paid into such fund and refunds paid in accordance with the provisions of section 3305(b); except that—"],[2,"(A) an amount equal to the amount of employee payments into the unemployment fund of a State may be used in the payment of cash benefits to individuals with respect to their disability, exclusive of expenses of administration;"],[2,"(B) the amounts specified by section 903 (c)(2) or 903(d)(4) of the Social Security Act may, subject to the conditions prescribed in such section, be used for expenses incurred by the State for administration of its unemployment compensation law and public employment offices;"],[2,"(C) nothing in this paragraph shall be construed to prohibit deducting an amount from unemployment compensation otherwise payable to an individual and using the amount so deducted to pay for health insurance, or the withholding of Federal, State, or local individual income tax, if the individual elected to have such deduction made and such deduction was made under a program approved by the Secretary of Labor;"],[2,"(D) amounts shall be deducted from unemployment benefits and used to repay overpayments as provided in section 303(g) of the Social Security Act;"],[2,"(E) amounts may be withdrawn for the payment of short-time compensation under a short-time compensation program (as defined under section 3306(v));"],[2,"(F) amounts may be withdrawn for the payment of allowances under a self-employment assistance program (as defined in section 3306(t)); and"],[2,"(G) with respect to amounts of covered unemployment compensation debt (as defined in section 6402(f)(4)) collected under section 6402(f)—"],[3,"(i) amounts may be deducted to pay any fees authorized under such section; and"],[3,"(ii) the penalties and interest described in section 6402(f)(4)(C) may be transferred to the appropriate State fund into which the State would have deposited such amounts had the person owing the debt paid such amounts directly to the State;"],[1,"(5) compensation shall not be denied in such State to any otherwise eligible individual for refusing to accept new work under any of the following conditions:"],[2,"(A) if the position offered is vacant due directly to a strike, lockout, or other labor dispute;"],[2,"(B) if the wages, hours, or other conditions of the work offered are substantially less favorable to the individual than those prevailing for similar work in the locality;"],[2,"(C) if as a condition of being employed the individual would be required to join a company union or to resign from or refrain from joining any bona fide labor organization;"],[1,"(6)(A) compensation is payable on the basis of service to which section 3309(a)(1) applies, in the same amount, on the same terms, and subject to the same conditions as compensation payable on the basis of other service subject to such law; except that—"],[2,"(i) with respect to services in an instructional, research, or principal administrative capacity for an educational institution to which section 3309(a)(1) applies, compensation shall not be payable based on such services for any week commencing during the period between two successive academic years or terms (or, when an agreement provides instead for a similar period between two regular but not successive terms, during such period) to any individual if such individual performs such services in the first of such academic years (or terms) and if there is a contract or reasonable assurance that such individual will perform services in any such capacity for any educational institution in the second of such academic years or terms,"],[2,"(ii) with respect to services in any other capacity for an educational institution to which section 3309(a)(1) applies—"],[3,"(I) compensation payable on the basis of such services may be denied to any individual for any week which commences during a period between 2 successive academic years or terms if such individual performs such services in the first of such academic years or terms and there is a reasonable assurance that such individual will perform such services in the second of such academic years or terms, except that"],[3,"(II) if compensation is denied to any individual for any week under subclause (I) and such individual was not offered an opportunity to perform such services for the educational institution for the second of such academic years or terms, such individual shall be entitled to a retroactive payment of the compensation for each week for which the individual filed a timely claim for compensation and for which compensation was denied solely by reason of subclause (I),"],[2,"(iii) with respect to any services described in clause (i) or (ii), compensation payable on the basis of such services shall be denied to any individual for any week which commences during an established and customary vacation period or holiday recess if such individual performs such services in the period immediately before such vacation period or holiday recess, and there is a reasonable assurance that such individual will perform such services in the period immediately following such vacation period or holiday recess,"],[2,"(iv) with respect to any services described in clause (i) or (ii), compensation payable on the basis of services in any such capacity shall be denied as specified in clauses (i), (ii), and (iii) to any individual who performed such services in an educational institution while in the employ of an educational service agency, and for this purpose the term \"educational service agency\" means a governmental agency or governmental entity which is established and operated exclusively for the purpose of providing such services to one or more educational institutions,"],[2,"(v) with respect to services to which section 3309(a)(1) applies, if such services are provided to or on behalf of an educational institution, compensation may be denied under the same circumstances as described in clauses (i) through (iv), and"],[2,"(vi) with respect to services described in clause (ii), clauses (iii) and (iv) shall be applied by substituting \"may be denied\" for \"shall be denied\", and"],[1,"(B) payments (in lieu of contributions) with respect to service to which section 3309(a)(1) applies may be made into the State unemployment fund on the basis set forth in section 3309(a)(2);"],[1,"(7) an individual who has received compensation during his benefit year is required to have had work since the beginning of such year in order to qualify for compensation in his next benefit year;"],[1,"(8) compensation shall not be denied to an individual for any week because he is in training with the approval of the State agency (or because of the application, to any such week in training, of State law provisions relating to availability for work, active search for work, or refusal to accept work);"],[1,"(9)(A) compensation shall not be denied or reduced to an individual solely because he files a claim in another State (or a contiguous country with which the United States has an agreement with respect to unemployment compensation) or because he resides in another State (or such a contiguous country) at the time he files a claim for unemployment compensation;"],[1,"(B) the State shall participate in any arrangements for the payment of compensation on the basis of combining an individual's wages and employment covered under the State law with his wages and employment covered under the unemployment compensation law of other States which are approved by the Secretary of Labor in consultation with the State unemployment compensation agencies as reasonably calculated to assure the prompt and full payment of compensation in such situations. Any such arrangement shall include provisions for (i) applying the base period of a single State law to a claim involving the combining of an individual's wages and employment covered under two or more State laws, and (ii) avoiding duplicate use of wages and employment by reason of such combining;"],[1,"(10) compensation shall not be denied to any individual by reason of cancellation of wage credits or total reduction of his benefit rights for any cause other than discharge for misconduct connected with his work, fraud in connection with a claim for compensation, or receipt of disqualifying income;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/3304?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3304. Approval of State laws","tname":"Internal Revenue Code","by":{"0":"5","1":"3, 4, 1, 4"}},{"t":"usc","label":"26 U.S.C. § 3309","url":"https://www.law.cornell.edu/uscode/text/26/3309","subs":["(b)(1976)","(b)","(b)(1)","(b)(1)(A)","(b)(1)(B)","(a)","(a)(2)"],"stext":{"head":"§3309. State law coverage of services performed for nonprofit organizations or governmental entities","paras":[[0,"(a) State law requirements"],[0,"For purposes of section 3304(a)(6)—"],[1,"(1) except as otherwise provided in subsections (b) and (c), the services to which this paragraph applies are—"],[2,"(A) service excluded from the term \"employment\" solely by reason of paragraph (8) of section 3306(c), and"],[2,"(B) service excluded from the term \"employment\" solely by reason of paragraph (7) of section 3306(c); and"],[1,"(2) the State law shall provide that a governmental entity, including an Indian tribe, or any other organization (or group of governmental entities or other organizations) which, but for the requirements of this paragraph, would be liable for contributions with respect to service to which paragraph (1) applies may elect, for such minimum period and at such time as may be provided by State law, to pay (in lieu of such contributions) into the State unemployment fund amounts equal to the amounts of compensation attributable under the State law to such service. The State law may provide safeguards to ensure that governmental entities or other organizations so electing will make the payments required under such elections."],[0,"(b) Section not to apply to certain service"],[0,"This section shall not apply to service performed—"],[1,"(1) in the employ of (A) a church or convention or association of churches, (B) an organization which is operated primarily for religious purposes and which is operated, supervised, controlled, or principally supported by a church or convention or association of churches, or (C) an elementary or secondary school which is operated primarily for religious purposes, which is described in section 501(c)(3), and which is exempt from tax under section 501(a);"],[1,"(2) by a duly ordained, commissioned, or licensed minister of a church in the exercise of his ministry or by a member of a religious order in the exercise of duties required by such order;"],[1,"(3) in the employ of a governmental entity referred to in paragraph (7) of section 3306(c), if such service is performed by an individual in the exercise of his duties—"],[2,"(A) as an elected official;"],[2,"(B) as a member of a legislative body, or a member of the judiciary, of a State or political subdivision thereof, or of an Indian tribe;"],[2,"(C) as a member of the State National Guard or Air National Guard;"],[2,"(D) as an employee serving on a temporary basis in case of fire, storm, snow, earthquake, flood, or similar emergency;"],[2,"(E) in a position which, under or pursuant to the State or tribal law, is designated as (i) a major nontenured policymaking or advisory position, or (ii) a policymaking or advisory position the performance of the duties of which ordinarily does not require more than 8 hours per week; or"],[2,"(F) as an election official or election worker if the amount of remuneration received by the individual during the calendar year for services as an election official or election worker is less than $1,000;"],[1,"(4) in a facility conducted for the purpose of carrying out a program of—"],[2,"(A) rehabilitation for individuals whose earning capacity is impaired by age or physical or mental deficiency or injury, or"],[2,"(B) providing remunerative work for individuals who because of their impaired physical or mental capacity cannot be readily absorbed in the competitive labor market,"],[1,"by an individual receiving such rehabilitation or remunerative work;"],[1,"(5) as part of an unemployment work-relief or work-training program assisted or financed in whole or in part by any Federal agency or an agency of a State or political subdivision thereof or of an Indian tribe, by an individual receiving such work relief or work training; and"],[1,"(6) by an inmate of a custodial or penal institution."],[0,"(c) Nonprofit organizations must employ 4 or more"],[0,"This section shall not apply to service performed during any calendar year in the employ of any organization unless on each of some 20 days during such calendar year or the preceding calendar year, each day being in a different calendar week, the total number of individuals who were employed by such organization in employment (determined without regard to section 3306(c)(8) and by excluding service to which this section does not apply by reason of subsection (b)) for some portion of the day (whether or not at the same moment of time) was 4 or more."],[0,"(d) Election by Indian tribe"],[0,"The State law shall provide that an Indian tribe may make contributions for employment as if the employment is within the meaning of section 3306 or make payments in lieu of contributions under this section, and shall provide that an Indian tribe may make separate elections for itself and each subdivision, subsidiary, or business enterprise wholly owned by such Indian tribe. State law may require a tribe to post a payment bond or take other reasonable measures to assure the making of payments in lieu of contributions under this section. Notwithstanding the requirements of section 3306(a)(6), if, within 90 days of having received a notice of delinquency, a tribe fails to make contributions, payments in lieu of contributions, or payment of penalties or interest (at amounts or rates comparable to those applied to all other employers covered under the State law) assessed with respect to such failure, or if the tribe fails to post a required payment bond, then service for the tribe shall not be excepted from employment under section 3306(c)(7) until any such failure is corrected. This subsection shall apply to an Indian tribe within the meaning of section 4(e) of the Indian Self-Determination and Education Assistance Act (25 U.S.C. 5304(e))."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/3309?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3309. State law coverage of services performed for nonprofit organizations or governmental entities","tname":"Internal Revenue Code","by":{"0":"1, 4, 5, 6","1":"3, 4, 13, 4, 8, 33, 2, 4, 6, 10, 12, 13, 15, 16, 23, 24, 30, 31, 34","2":"6, 4, 6, 6–7, 56"}},{"t":"usc","label":"28 U.S.C. § 1257","url":"https://www.law.cornell.edu/uscode/text/28/1257","by":{"0":"3"}},{"t":"usc","label":"42 U.S.C. § 2000bb","url":"https://www.law.cornell.edu/uscode/text/42/2000bb","stext":{"head":"§2000bb. Congressional findings and declaration of purposes","paras":[[0,"(a) Findings"],[0,"The Congress finds that—"],[1,"(1) the framers of the Constitution, recognizing free exercise of religion as an unalienable right, secured its protection in the First Amendment to the Constitution;"],[1,"(2) laws \"neutral\" toward religion may burden religious exercise as surely as laws intended to interfere with religious exercise;"],[1,"(3) governments should not substantially burden religious exercise without compelling justification;"],[1,"(4) in Employment Division v. Smith, 494 U.S. 872 (1990) the Supreme Court virtually eliminated the requirement that the government justify burdens on religious exercise imposed by laws neutral toward religion; and"],[1,"(5) the compelling interest test as set forth in prior Federal court rulings is a workable test for striking sensible balances between religious liberty and competing prior governmental interests."],[0,"(b) Purposes"],[0,"The purposes of this chapter are—"],[1,"(1) to restore the compelling interest test as set forth in Sherbert v. Verner, 374 U.S. 398 (1963) and Wisconsin v. Yoder, 406 U.S. 205 (1972) and to guarantee its application in all cases where free exercise of religion is substantially burdened; and"],[1,"(2) to provide a claim or defense to persons whose religious exercise is substantially burdened by government."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000bb?type=usc&year=mostrecent&link-type=html"},"head":"§2000bb. Congressional findings and declaration of purposes","tname":"The Public Health and Welfare","by":{"0":"42","1":"19","3":"11"}},{"t":"usc","label":"42 U.S.C. § 2000cc","url":"https://www.law.cornell.edu/uscode/text/42/2000cc","stext":{"head":"§2000cc. Protection of land use as religious exercise","paras":[[0,"(a) Substantial burdens"],[0,"(1) General rule"],[1,"No government shall impose or implement a land use regulation in a manner that imposes a substantial burden on the religious exercise of a person, including a religious assembly or institution, unless the government demonstrates that imposition of the burden on that person, assembly, or institution—"],[2,"(A) is in furtherance of a compelling governmental interest; and"],[2,"(B) is the least restrictive means of furthering that compelling governmental interest."],[0,"(2) Scope of application"],[1,"This subsection applies in any case in which—"],[2,"(A) the substantial burden is imposed in a program or activity that receives Federal financial assistance, even if the burden results from a rule of general applicability;"],[2,"(B) the substantial burden affects, or removal of that substantial burden would affect, commerce with foreign nations, among the several States, or with Indian tribes, even if the burden results from a rule of general applicability; or"],[2,"(C) the substantial burden is imposed in the implementation of a land use regulation or system of land use regulations, under which a government makes, or has in place formal or informal procedures or practices that permit the government to make, individualized assessments of the proposed uses for the property involved."],[0,"(b) Discrimination and exclusion"],[0,"(1) Equal terms"],[1,"No government shall impose or implement a land use regulation in a manner that treats a religious assembly or institution on less than equal terms with a nonreligious assembly or institution."],[0,"(2) Nondiscrimination"],[1,"No government shall impose or implement a land use regulation that discriminates against any assembly or institution on the basis of religion or religious denomination."],[0,"(3) Exclusions and limits"],[1,"No government shall impose or implement a land use regulation that—"],[2,"(A) totally excludes religious assemblies from a jurisdiction; or"],[2,"(B) unreasonably limits religious assemblies, institutions, or structures within a jurisdiction."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000cc?type=usc&year=mostrecent&link-type=html"},"head":"§2000cc. Protection of land use as religious exercise","tname":"The Public Health and Welfare","by":{"0":"42","1":"19","3":"11"}},{"t":"reg","label":"76 Fed. Reg. 46,621","url":"https://www.govinfo.gov/link/fr/76/46621","by":{"0":"32","2":"54"}},{"t":"case","label":"BP p.l.c. v. Mayor & City Council of Baltimore","cite":"593 U.S. 230","y":2021,"id":"2020/19-1189","sc":1,"sum":"Where defendant energy companies premised 28 U. S. C. §1447(d) removal in part on the federal officer removal statute, §1442, the Fourth Circuit erred in holding that it lacked jurisdiction to consider all grounds for removal rejected by the District Court.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"24"}},{"t":"case","label":"Better Business Bureau of Washington, D.C., Inc. v. United States","cite":"326 U.S. 279","y":1945,"id":"scdb/1945-020","sc":1,"sum":"1. A Better Business Bureau, an important if not the primary object of which is to promote not only an ethical but also a profitable business community, held not exempt from social security taxes as a corporation \"organized and operated exclusively for scientific or educational purposes,\" within the meaning of § 811 (b) (8) of the Social Security Act. P. 282. This conclusion is supported by the legislative history …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16, 17, 20, 35"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"1":"27, 32"}},{"t":"case","label":"(III) Cases—Continued: Chamber of Commerce v. Whiting","cite":"563 U.S. 582","y":2011,"id":"2010/09-115","sc":1,"sum":"The Court held that Arizona laws requiring employers to verify the employment eligibility of their employees through a federal database was not unconstitutional.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Delaware v. Pennsylvania","cite":"598 U.S. 115","y":2023,"id":"2022/22o145","sc":1,"op":2,"sum":"The Court held that the Federal Disposition Act applies to unclaimed or uncashed checks issued by MoneyGram Payments Systems, and thus that they must be returned to the state where they were purchased.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Dumaine Farms v. Commissioner","cite":"73 T.C. 650","y":1980,"url":"https://www.courtlistener.com/c/T.C./73/650/","by":{"1":"17, 18","2":"60"}},{"t":"case","label":"Duquesne Univ. of the Holy Spirit v. NLRB","cite":"947 F.3d 824","y":2020,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/947/824/","by":{"1":"21, 34"}},{"t":"case","label":"Freeman v. Quicken Loans, Inc.","cite":"566 U.S. 624","y":2012,"id":"2011/10-1042","sc":1,"sum":"The Court held that Section 8(b) of the Real Estate Settlement Procedures Act prohibits a real estate service provider from charging an unearned fee if the fee is divided between two or more parties.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Golden Rule Church Ass’n v. Commissioner","cite":"41 T.C. 719","y":1964,"url":"https://www.courtlistener.com/c/T.C./41/719/","by":{"1":"17, 18","2":"62"}},{"t":"case","label":"Hernandez v. Commissioner","cite":"490 U.S. 680","y":1989,"id":"1988/87-963","sc":1,"sum":"Payments made to the Church's branch churches for auditing and training services are not deductible charitable contributions under § 170.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19, 28-30","2":"39, 44","3":"20"}},{"t":"case","label":"Iancu v. Brunetti","cite":"588 U.S. 388","y":2019,"id":"2018/18-302","sc":1,"sum":"The Lanham Act prohibition on the registration of “immoral” or “scandalous” trademarks infringes the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"27"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Living Faith, Inc. v. Commissioner","cite":"950 F.2d 365","y":1991,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/950/365/","ar":2,"by":{"1":"17, 18, 21, 35","2":"59–60"}},{"t":"case","label":"Mayo Clinic v. United States","cite":"997 F.3d 789","y":2021,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/997/789/","by":{"1":"17"}},{"t":"case","label":"Michigan v. Long","cite":"463 U.S. 1032","y":1983,"id":"1982/82-256","sc":1,"ar":4,"sum":"The Court, after admitting that it had not developed \"a satisfying and consistent approach\" regarding lower court references to independent state grounds, held that it had jurisdiction in the case. The Court held that when state court decisions appeared to rest primarily on federal law, it would infer that state courts believed that federal law required them to do so.","sumSrc":"Oyez","by":{"1":"13","2":"55","3":"12"}},{"t":"case","label":"National Ass’n of Mfrs. v. Department of Defense","cite":"583 U.S. 109","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"O’Brien v. Skinner","cite":"414 U.S. 524","y":1974,"id":"1973/72-1058","sc":1,"sum":"The challenged provisions as thus construed, which raise no question of disenfranchisement of persons convicted of criminal conduct and permit incarcerated 'persons to register and vote by absentee means if confined in a county where they are not residents, violate the Equal Protection Clause of the Fourteenth Amendment, as they arbitrarily discriminate between categories of qualified voters. - Pp. 528-531. 31 N. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Polselli v. IRS","cite":"598 U.S. 432","y":2023,"id":"2022/21-1599","sc":1,"sum":"When the Internal Revenue Service issues a summons pursuant to 26 U. S. C. §7602(a) in aid of collecting a tax liability, the exception to the notice requirement in §7609(c)(2)(D)(i) applies even if the delinquent taxpayer has no legal interest in the accounts or records summoned.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"22"}},{"t":"case","label":"Presbyterian & Reformed Publ’g Co. v. Commissioner","cite":"743 F.2d 148","y":1984,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/743/148/","by":{"1":"17","2":"62"}},{"t":"case","label":"Ramirez v. Collier","cite":"595 U.S. 411","y":2022,"id":"2021/21-5592","sc":1,"ar":1,"sum":"Petitioner Ramirez is likely to succeed on his claims under the Religious Land Use and Institutionalized Persons Act of 2000 because Texas’s restrictions on religious touch and audible prayer in the execution chamber burden religious exercise and are not the least restrictive means of furthering the State’s compelling interests.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"20","3":"24"}},{"t":"case","label":"Rumsfeld v. Forum for Academic & Institutional Rights, Inc.","cite":"547 U.S. 47","y":2006,"id":"2005/04-1152","sc":1,"sum":"The Supreme Court, in a unanimous opinion written by Chief Justice John Roberts, held that the Solomon Amendment regulated conduct, not speech, and was therefore constitutional. Including military recruiters in receptions and interviews does not necessarily indicate university endorsement of the recruiters, so requiring their inclusion does not constitute compelled speech in violation of the First Amendment.","sumSrc":"Oyez","by":{"1":"2, 12, 32"}},{"t":"case","label":"United States v. Ballard","cite":"322 U.S. 78","y":1944,"id":"scdb/1943-132","sc":1,"sum":"Upon an indictment charging use of the mails to defraud, and conspiracy so to do, respondents were convicted in the District Court. The indictment charged a scheme to defraud through representations-involving respondents' religious doctrines or beliefs-which were alleged to be false and known by the respondents to be false. Holding that the District Court had restricted the jury to the issue -of respondents' good …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"United States v. Hansen","cite":"599 U.S. 762","y":2023,"id":"2022/22-179","sc":1,"sum":"Title 8 U. S. C. §1324(a)(1)(A)(iv)—which criminalizes “encouraging or inducing” illegal immigration—forbids only the purposeful solicitation and facilitation of specific acts known to violate federal law and is not unconstitutionally overbroad.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"33"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"1":"27"}},{"t":"law","label":"Pub. L. No. 91-373","url":"https://www.govinfo.gov/link/statute/84/698","by":{"1":"4"}},{"t":"usc","label":"26 U.S.C. § 3306","url":"https://www.law.cornell.edu/uscode/text/26/3306","subs":["(a)","(c)","(c)(8)(1964)"],"stext":{"head":"§3306. Definitions","paras":[[0,"(a) Employer"],[0,"For purposes of this chapter—"],[0,"(1) In general"],[1,"The term \"employer\" means, with respect to any calendar year, any person who—"],[2,"(A) during any calendar quarter in the calendar year or the preceding calendar year paid wages of $1,500 or more, or"],[2,"(B) on each of some 20 days during the calendar year or during the preceding calendar year, each day being in a different calendar week, employed at least one individual in employment for some portion of the day."],[1,"For purposes of this paragraph, there shall not be taken into account any wages paid to, or employment of, an employee performing domestic services referred to in paragraph (3)."],[0,"(2) Agricultural labor"],[1,"In the case of agricultural labor, the term \"employer\" means, with respect to any calendar year, any person who—"],[2,"(A) during any calendar quarter in the calendar year or the preceding calendar year paid wages of $20,000 or more for agricultural labor, or"],[2,"(B) on each of some 20 days during the calendar year or during the preceding calendar year, each day being in a different calendar week, employed at least 10 individuals in employment in agricultural labor for some portion of the day."],[0,"(3) Domestic service"],[1,"In the case of domestic service in a private home, local college club, or local chapter of a college fraternity or sorority, the term \"employer\" means, with respect to any calendar year, any person who during any calendar quarter in the calendar year or the preceding calendar year paid wages in cash of $1,000 or more for such service."],[0,"(4) Special rule"],[1,"A person treated as an employer under paragraph (3) shall not be treated as an employer with respect to wages paid for any service other than domestic service referred to in paragraph (3) unless such person is treated as an employer under paragraph (1) or (2) with respect to such other service."],[0,"(b) Wages"],[0,"For purposes of this chapter, the term \"wages\" means all remuneration for employment, including the cash value of all remuneration (including benefits) paid in any medium other than cash; except that such term shall not include—"],[1,"(1) that part of the remuneration which, after remuneration (other than remuneration referred to in the succeeding paragraphs of this subsection) equal to $7,000 with respect to employment has been paid to an individual by an employer during any calendar year, is paid to such individual by such employer during such calendar year. If an employer (hereinafter referred to as successor employer) during any calendar year acquires substantially all the property used in a trade or business of another employer (hereinafter referred to as a predecessor), or used in a separate unit of a trade or business of a predecessor, and immediately after the acquisition employs in his trade or business an individual who immediately prior to the acquisition was employed in the trade or business of such predecessor, then, for the purpose of determining whether the successor employer has paid remuneration (other than remuneration referred to in the succeeding paragraphs of this subsection) with respect to employment equal to $7,000 to such individual during such calendar year, any remuneration (other than remuneration referred to in the succeeding paragraphs of this subsection) with respect to employment paid (or considered under this paragraph as having been paid) to such individual by such predecessor during such calendar year and prior to such acquisition shall be considered as having been paid by such successor employer;"],[1,"(2) the amount of any payment (including any amount paid by an employer for insurance or annuities, or into a fund, to provide for any such payment) made to, or on behalf of, an employee or any of his dependents under a plan or system established by an employer which makes provision for his employees generally (or for his employees generally and their dependents) or for a class or classes of his employees (or for a class or classes of his employees and their dependents), on account of—"],[2,"(A) sickness or accident disability (but, in the case of payments made to an employee or any of his dependents, this subparagraph shall exclude from the term \"wages\" only payments which are received under a workmen's compensation law), or"],[2,"(B) medical or hospitalization expenses in connection with sickness or accident disability, or"],[2,"(C) death;"],[1,"[(3) Repealed. Pub. L. 98–21, title III, §324(b)(3)(B), Apr. 20, 1983, 97 Stat. 124]"],[1,"(4) any payment on account of sickness or accident disability, or medical or hospitalization expenses in connection with sickness or accident disability, made by an employer to, or on behalf of, an employee after the expiration of 6 calendar months following the last calendar month in which the employee worked for such employer;"],[1,"(5) any payment made to, or on behalf of, an employee or his beneficiary—"],[2,"(A) from or to a trust described in section 401(a) which is exempt from tax under section 501(a) at the time of such payment unless such payment is made to an employee of the trust as remuneration for services rendered as such employee and not as a beneficiary of the trust, or"],[2,"(B) under or to an annuity plan which, at the time of such payment, is a plan described in section 403(a),"],[2,"(C) under a simplified employee pension (as defined in section 408(k)(1)), other than any contributions described in section 408(k)(6),"],[2,"(D) under or to an annuity contract described in section 403(b), other than a payment for the purchase of such contract which is made by reason of a salary reduction agreement (whether evidenced by a written instrument or otherwise),"],[2,"(E) under or to an exempt governmental deferred compensation plan (as defined in section 3121(v)(3)),"],[2,"(F) to supplement pension benefits under a plan or trust described in any of the foregoing provisions of this paragraph to take into account some portion or all of the increase in the cost of living (as determined by the Secretary of Labor) since retirement but only if such supplemental payments are under a plan which is treated as a welfare plan under section 3(2)(B)(ii) of the Employee Retirement Income Security Act of 1974,"],[2,"(G) under a cafeteria plan (within the meaning of section 125) if such payment would not be treated as wages without regard to such plan and it is reasonable to believe that (if section 125 applied for purposes of this section) section 125 would not treat any wages as constructively received, or"],[2,"(H) under an arrangement to which section 408(p) applies, other than any elective contributions under paragraph (2)(A)(i) thereof,1"],[1,"(6) the payment by an employer (without deduction from the remuneration of the employee)—"],[2,"(A) of the tax imposed upon an employee under section 3101, or"],[2,"(B) of any payment required from an employee under a State unemployment compensation law,"],[1,"with respect to remuneration paid to an employee for domestic service in a private home of the employer or for agricultural labor;"],[1,"(7) remuneration paid in any medium other than cash to an employee for service not in the course of the employer's trade or business;"],[1,"[(8) Repealed. Pub. L. 98–21, title III, §324(b)(3)(B), Apr. 20, 1983, 97 Stat. 124]"],[1,"(9) remuneration paid to or on behalf of an employee if (and to the extent that) at the time of the payment of such remuneration it is reasonable to believe that a corresponding deduction is allowable under section 217 (determined without regard to section 274(n));"],[1,"(10) any payment or series of payments by an employer to an employee or any of his dependents which is paid—"],[2,"(A) upon or after the termination of an employee's employment relationship because of (i) death, or (ii) retirement for disability, and"],[2,"(B) under a plan established by the employer which makes provision for his employees generally or a class or classes of his employees (or for such employees or class or classes of employees and their dependents),"],[1,"other than any such payment or series of payments which would have been paid if the employee's employment relationship had not been so terminated;"],[1,"(11) remuneration for agricultural labor paid in any medium other than cash;"],[1,"[(12) Repealed. Pub. L. 113–295, div. A, title II, §221(a)(19)(B)(vi), Dec. 19, 2014, 128 Stat. 4040]"],[1,"(13) any payment made, or benefit furnished, to or for the benefit of an employee if at the time of such payment or such furnishing it is reasonable to believe that the employee will be able to exclude such payment or benefit from income under section 127, 129, 134(b)(4), or 134(b)(5);"],[1,"(14) the value of any meals or lodging furnished by or on behalf of the employer if at the time of such furnishing it is reasonable to believe that the employee will be able to exclude such items from income under section 119;"],[1,"(15) any payment made by an employer to a survivor or the estate of a former employee after the calendar year in which such employee died;"],[1,"(16) any benefit provided to or on behalf of an employee if at the time such benefit is provided it is reasonable to believe that the employee will be able to exclude such benefit from income under section 74(c), 108(f)(4), 117, or 132;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/3306?type=usc&year=mostrecent&link-type=html"},"head":"§3306. Definitions","tname":"Internal Revenue Code","by":{"1":"3, 3","2":"6"}},{"t":"usc","label":"26 U.S.C. § 170","url":"https://www.law.cornell.edu/uscode/text/26/170","subs":["(c)(2)(B)"],"by":{"1":"29"}},{"t":"usc","label":"26 U.S.C. § 1426","url":"https://www.law.cornell.edu/uscode/text/26/1426","subs":["(b)(8)(1940)"],"by":{"1":"16"}},{"t":"usc","label":"29 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/29/151","by":{"1":"21"}},{"t":"usc","label":"42 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/42/301","by":{"1":"3, 16"}},{"t":"usc","label":"42 U.S.C. § 2000e-1","url":"https://www.law.cornell.edu/uscode/text/42/2000e-1","subs":["(a)"],"by":{"1":"29"}},{"t":"reg","label":"52 Fed. Reg. 27,072","url":"https://www.govinfo.gov/link/fr/52/27072","by":{"1":"25"}},{"t":"reg","label":"89 Fed. Reg. 90,053","url":"https://www.govinfo.gov/link/fr/89/90053","by":{"1":"4"}},{"t":"case","label":"Agostini v. Felton","cite":"521 U.S. 203","y":1997,"id":"1996/96-552","sc":1,"sum":"The Court held that there was no evidence to support its former presumption that the entrance of public school teachers into parochial schools will inevitably lead to the indoctrination of state-sponsored religion.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"Am. Legion v. Am. Humanist Ass’n","cite":"588 U.S. 29","y":2019,"url":"https://supreme.justia.com/cases/federal/us/588/29/","sc":1,"by":{"2":"33"}},{"t":"case","label":"Bd. of Educ. of Kiryas Joel Vill. Sch. Dist. v. Grumet","cite":"512 U.S. 687","y":1994,"id":"1993/93-517","sc":1,"sum":"In a 6-to-3 decision, the Court held that the statute's purpose was to exclude all but those who lived in and practiced the village enclave's extreme form of Judaism.","sumSrc":"Oyez","by":{"2":"35, 36, 37, 47"}},{"t":"case","label":"Bostock v. Clayton Cnty.","cite":"590 U.S. 644","y":2020,"id":"2019/17-1618","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"2":"62"}},{"t":"case","label":"Bowen v. Kendrick","cite":"487 U.S. 589","y":1988,"id":"1987/87-253","sc":1,"sum":"In a 5-to-4 decision, the Court held that the \"advancement of religion\" was not AFLA's primary effect. Although it funded religious and other institutions without expressly prohibiting the use of such funds for religious purposes, AFLA required potential recipients to reveal what services they intended to provide and how they would provide them. Thus, the government could protect against the misuse of its funds.","sumSrc":"Oyez","by":{"2":"28, 30"}},{"t":"case","label":"Cmty. Lutheran Sch. v. Iowa Dep’t of Job Serv.","cite":"326 N.W.2d 286","y":1982,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W.2d/326/286/","by":{"2":"61"}},{"t":"case","label":"Emp. Sec. Admin. v. Balt. Lutheran High Sch. Ass’n","cite":"436 A.2d 481","y":1981,"court":"Md.","url":"https://www.courtlistener.com/c/A.2d/436/481/","by":{"2":"61"}},{"t":"case","label":"Gillette v. United States","cite":"401 U.S. 437","y":1971,"id":"1970/85","sc":1,"op":7,"sum":"Petitioner in No. 85, who was convicted for failure to report for induction, and petitioner in No. 325, who sought discharge from the armed forces upon receipt of orders for Vietnam duty, claim exemption from 'military service because of their conscientious objection to participation in the Vietnam conflict, as an \"unjust\" war, pursuant to § 6 (j)' of the Military Selective Service Act of 1967. That section provides …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"36, 37","3":"18"}},{"t":"case","label":"Jimmy Swaggart Ministries v. Board of Equalization of California","cite":"493 U.S. 378","y":1990,"id":"1989/88-1374","sc":1,"sum":"Basing its unanimous decision on the fact that California's sales and use tax was not a flat tax, affected only a small portion of retail sales, and was neutrally applied, the Court found the taxes constitutional.","sumSrc":"Oyez","by":{"2":"39"}},{"t":"case","label":"Kedroff v. St. Nicholas Cathedral of Russian Orthodox Church in North America","cite":"44 U.S. 94","y":1952,"url":"https://supreme.justia.com/cases/federal/us/44/94/","sc":1,"op":3,"by":{"2":"48, 49, 50"}},{"t":"case","label":"Lemon v. Kurtzman","cite":"403 U.S. 602","y":1971,"id":"1970/89","sc":1,"ar":2,"sum":"The Court found that Pennsylvania and Rhode Island statutes granting salary supplements to teachers at \"church-related educational institutions\" was unconstitutional for violating the Establishment Clause of the First Amendment. The case established the Lemon Test for determining if the government is becoming too involved in religious activities.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Locke v. Davey","cite":"540 U.S. 712","y":2004,"id":"2003/02-1315","sc":1,"sum":"The Court ruled that a state does not violate the First Amendment's free exercise clause when it funds secular college majors but excludes devotional theology majors.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Lynch v. Donnelly","cite":"465 U.S. 668","y":1984,"id":"1983/82-1256","sc":1,"sum":"The Court held that a nativity scene in the city's shopping district did not violate the Establishment Clause of the First Amendment.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Nampa Christian Schs. Found. Inc. v. State, Dep’t of Emp.","cite":"719 P.2d 1178","y":1986,"court":"Idaho","url":"https://www.courtlistener.com/c/P.2d/719/1178/","by":{"2":"61"}},{"t":"case","label":"Olsen v. Drug Enf’t Admin.","cite":"878 F.2d 1458","y":1989,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/878/1458/","sum":"Noting “political pressure to repeal thousands of narrow religious exemptions already enacted, lest they be expanded to become universal exemptions”.","sumSrc":"brief:2","by":{"2":"47"}},{"t":"case","label":"Rojas v. Fitch","cite":"127 F.3d 184","y":1997,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/127/184/","by":{"2":"22, 58–59"}},{"t":"case","label":"Samaritan Inst. v. Prince-Walker","cite":"883 P.2d 3","y":1994,"court":"Colo.","url":"https://www.courtlistener.com/c/P.2d/883/3/","by":{"2":"61"}},{"t":"case","label":"Sch. Dist. of Abington Twp. v. Schempp","cite":"374 U.S. 203","y":1963,"id":"1962/142","sc":1,"op":1,"sum":"The Court found that mandatory daily Bible readings and prayer in Pennsylvania public schools violated the First Amendment rights of its students.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"Schwartz v. Unemployment Ins. Comm’n","cite":"895 A.2d 965","y":2006,"court":"Me.","url":"https://www.courtlistener.com/c/A.2d/895/965/","by":{"2":"60"}},{"t":"case","label":"State ex rel. Kalal v. Cir. Ct. for Dane Cnty.","cite":"2004 WI 58","url":"https://www.courtlistener.com/c/WI/2004/58/","by":{"2":"62"}},{"t":"case","label":"Terwilliger v. St. Vincent Infirmary Med. Ctr.","cite":"804 S.W.2d 696","y":1991,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W.2d/804/696/","by":{"2":"61"}},{"t":"case","label":"Tex. Monthly, Inc. v. Bullock","cite":"489 U.S. 1","y":1989,"id":"1988/87-1245","sc":1,"sum":"Justice William J. Brennan Jr. delivered the judgment for 6-3 court a wrote a plurality opinion joined by Justices John Paul Stevens and Thurgood Marshall. In the Brennan's view, the Texas government \"directs a subsidy exclusively to religious organizations\" by providing the exemption. The Court referred to its decision in Lemon v. Kurtzman , which required legislation affecting religion to have a secular purpose.","sumSrc":"Oyez","by":{"2":"33"}},{"t":"case","label":"United States v. Lee","cite":"455 U.S. 252","y":1982,"id":"1981/80-767","sc":1,"sum":"The Supreme Court held that the §1402(g) exemption only applied to self-employed individuals, not employers and employees like those involved in this case. The Court held that the tax was not unconstitutional as applied. By becoming an employer, Lee entered into commercial activity and accepted certain limits on the exercise of his beliefs.","sumSrc":"Oyez","by":{"2":"39, 44","3":"20"}},{"t":"case","label":"Ysleta Del Sur Pueblo v. Texas","cite":"596 U.S. 685","y":2022,"id":"2021/20-493","sc":1,"sum":"The federal legislation at issue—the Ysleta del Sur and Alabama and Coushatta Indian Tribes of Texas Restoration Act—bans as a matter of federal law on tribal lands only those gaming activities also banned in Texas.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"58"}},{"t":"case","label":"Zubik v. Burwell","cite":"578 U.S. 403","y":2016,"id":"2015/14-1418","sc":1,"sum":"The Court determined that insurance companies could potentially provide contraceptive coverage to employees of organizations that object to such coverage on religious grounds without the organizations needing to provide notification.","sumSrc":"Oyez","by":{"2":"54"}},{"t":"usc","label":"26 U.S.C. § 3127","url":"https://www.law.cornell.edu/uscode/text/26/3127","subs":["(b)"],"by":{"2":"16, 46"}},{"t":"usc","label":"26 U.S.C. § 5000A","url":"https://www.law.cornell.edu/uscode/text/26/5000A","subs":["(d)(2)(A)(i)(II)","(d)(2)(B)(ii)(II)"],"by":{"2":"46, 46"}},{"t":"usc","label":"26 U.S.C. § 7611","url":"https://www.law.cornell.edu/uscode/text/26/7611","by":{"2":"46"}},{"t":"usc","label":"26 U.S.C. § 508","url":"https://www.law.cornell.edu/uscode/text/26/508","subs":["(c)(1)(A)"],"by":{"2":"46"}},{"t":"usc","label":"26 U.S.C. § 3121","url":"https://www.law.cornell.edu/uscode/text/26/3121","subs":["(b)(8)(A)"],"by":{"2":"46"}},{"t":"usc","label":"26 U.S.C. § 6033","url":"https://www.law.cornell.edu/uscode/text/26/6033","subs":["(a)(3)(A)(iii)"],"by":{"2":"46"}},{"t":"usc","label":"29 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/29/1002","subs":["(33)(A)"],"stext":{"head":"§1002. Definitions","paras":[[0,"For purposes of this subchapter:"],[0,"(1) The terms \"employee welfare benefit plan\" and \"welfare plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that such plan, fund, or program was established or is maintained for the purpose of providing for its participants or their beneficiaries, through the purchase of insurance or otherwise, (A) medical, surgical, or hospital care or benefits, or benefits in the event of sickness, accident, disability, death or unemployment, or vacation benefits, apprenticeship or other training programs, or day care centers, scholarship funds, or prepaid legal services, or (B) any benefit described in section 186(c) of this title (other than pensions on retirement or death, and insurance to provide such pensions)."],[0,"(2)(A) Except as provided in subparagraph (B), the terms \"employee pension benefit plan\" and \"pension plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that by its express terms or as a result of surrounding circumstances such plan, fund, or program—"],[1,"(i) provides retirement income to employees, or"],[1,"(ii) results in a deferral of income by employees for periods extending to the termination of covered employment or beyond,"],[0,"regardless of the method of calculating the contributions made to the plan, the method of calculating the benefits under the plan or the method of distributing benefits from the plan. A distribution from a plan, fund, or program shall not be treated as made in a form other than retirement income or as a distribution prior to termination of covered employment solely because such distribution is made to an employee who has attained age 62 and who is not separated from employment at the time of such distribution."],[0,"(B) The Secretary may by regulation prescribe rules consistent with the standards and purposes of this chapter providing one or more exempt categories under which—"],[1,"(i) severance pay arrangements, and"],[1,"(ii) supplemental retirement income payments, under which the pension benefits of retirees or their beneficiaries are supplemented to take into account some portion or all of the increases in the cost of living (as determined by the Secretary of Labor) since retirement,"],[0,"shall, for purposes of this subchapter, be treated as welfare plans rather than pension plans. In the case of any arrangement or payment a principal effect of which is the evasion of the standards or purposes of this chapter applicable to pension plans, such arrangement or payment shall be treated as a pension plan. An applicable voluntary early retirement incentive plan (as defined in section 457(e)(11)(D)(ii) of title 26) making payments or supplements described in section 457(e)(11)(D)(i) of title 26, and an applicable employment retention plan (as defined in section 457(f)(4)(C) of title 26) making payments of benefits described in section 457(f)(4)(A) of title 26, shall, for purposes of this subchapter, be treated as a welfare plan (and not a pension plan) with respect to such payments and supplements."],[0,"(C) A pooled employer plan shall be treated as—"],[1,"(i) a single employee pension benefit plan or single pension plan; and"],[1,"(ii) a plan to which section 1060(a) of this title applies."],[0,"(3) The term \"employee benefit plan\" or \"plan\" means an employee welfare benefit plan or an employee pension benefit plan or a plan which is both an employee welfare benefit plan and an employee pension benefit plan."],[0,"(4) The term \"employee organization\" means any labor union or any organization of any kind, or any agency or employee representation committee, association, group, or plan, in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning an employee benefit plan, or other matters incidental to employment relationships; or any employees' beneficiary association organized for the purpose in whole or in part, of establishing such a plan."],[0,"(5) The term \"employer\" means any person acting directly as an employer, or indirectly in the interest of an employer, in relation to an employee benefit plan; and includes a group or association of employers acting for an employer in such capacity."],[0,"(6) The term \"employee\" means any individual employed by an employer."],[0,"(7) The term \"participant\" means any employee or former employee of an employer, or any member or former member of an employee organization, who is or may become eligible to receive a benefit of any type from an employee benefit plan which covers employees of such employer or members of such organization, or whose beneficiaries may be eligible to receive any such benefit."],[0,"(8) The term \"beneficiary\" means a person designated by a participant, or by the terms of an employee benefit plan, who is or may become entitled to a benefit thereunder."],[0,"(9) The term \"person\" means an individual, partnership, joint venture, corporation, mutual company, joint-stock company, trust, estate, unincorporated organization, association, or employee organization."],[0,"(10) The term \"State\" includes any State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, and the Canal Zone. The term \"United States\" when used in the geographic sense means the States and the Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act (43 U.S.C. 1331–1343)."],[0,"(11) The term \"commerce\" means trade, traffic, commerce, transportation, or communication between any State and any place outside thereof."],[0,"(12) The term \"industry or activity affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce, and includes any activity or industry \"affecting commerce\" within the meaning of the Labor Management Relations Act, 1947 [29 U.S.C. 141 et seq.], or the Railway Labor Act [45 U.S.C. 151 et seq.]."],[0,"(13) The term \"Secretary\" means the Secretary of Labor."],[0,"(14) The term \"party in interest\" means, as to an employee benefit plan—"],[1,"(A) any fiduciary (including, but not limited to, any administrator, officer, trustee, or custodian), counsel, or employee of such employee benefit plan;"],[1,"(B) a person providing services to such plan;"],[1,"(C) an employer any of whose employees are covered by such plan;"],[1,"(D) an employee organization any of whose members are covered by such plan;"],[1,"(E) an owner, direct or indirect, of 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of a corporation.1"],[2,"(ii) the capital interest or the profits interest of a partnership, or"],[2,"(iii) the beneficial interest of a trust or unincorporated enterprise,"],[1,"which is an employer or an employee organization described in subparagraph (C) or (D);"],[1,"(F) a relative (as defined in paragraph (15)) of any individual described in subparagraph (A), (B), (C), or (E);"],[1,"(G) a corporation, partnership, or trust or estate of which (or in which) 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of such corporation,"],[2,"(ii) the capital interest or profits interest of such partnership, or"],[2,"(iii) the beneficial interest of such trust or estate,"],[1,"is owned directly or indirectly, or held by persons described in subparagraph (A), (B), (C), (D), or (E);"],[1,"(H) an employee, officer, director (or an individual having powers or responsibilities similar to those of officers or directors), or a 10 percent or more shareholder directly or indirectly, of a person described in subparagraph (B), (C), (D), (E), or (G), or of the employee benefit plan; or"],[1,"(I) a 10 percent or more (directly or indirectly in capital or profits) partner or joint venturer of a person described in subparagraph (B), (C), (D), (E), or (G)."],[0,"The Secretary, after consultation and coordination with the Secretary of the Treasury, may by regulation prescribe a percentage lower than 50 percent for subparagraph (E) and (G) and lower than 10 percent for subparagraph (H) or (I). The Secretary may prescribe regulations for determining the ownership (direct or indirect) of profits and beneficial interests, and the manner in which indirect stockholdings are taken into account. Any person who is a party in interest with respect to a plan to which a trust described in section 501(c)(22) of title 26 is permitted to make payments under section 1403 of this title shall be treated as a party in interest with respect to such trust."],[0,"(15) The term \"relative\" means a spouse, ancestor, lineal descendant, or spouse of a lineal descendant."],[0,"(16)(A) The term \"administrator\" means—"],[1,"(i) the person specifically so designated by the terms of the instrument under which the plan is operated;"],[1,"(ii) if an administrator is not so designated, the plan sponsor; or"],[1,"(iii) in the case of a plan for which an administrator is not designated and a plan sponsor cannot be identified, such other person as the Secretary may by regulation prescribe."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1002?type=usc&year=mostrecent&link-type=html"},"head":"§1002. Definitions","tname":"Labor","by":{"2":"46","3":"10"}},{"t":"usc","label":"42 U.S.C. § 604a","url":"https://www.law.cornell.edu/uscode/text/42/604a","subs":["(j)"],"by":{"2":"27"}},{"t":"usc","label":"42 U.S.C. § 2000cc-1","url":"https://www.law.cornell.edu/uscode/text/42/2000cc-1","by":{"2":"16"}},{"t":"reg","label":"2 C.F.R. § 3474.15","url":"https://www.ecfr.gov/current/title-2/section-3474.15","subs":["(d)(1)"],"by":{"2":"27"}},{"t":"reg","label":"7 C.F.R. § 16.4","url":"https://www.ecfr.gov/current/title-7/section-16.4","subs":["(b)"],"by":{"2":"28"}},{"t":"reg","label":"24 C.F.R. § 5.109","url":"https://www.ecfr.gov/current/title-24/section-5.109","subs":["(e)"],"by":{"2":"28"}},{"t":"reg","label":"45 C.F.R. § 87.3","url":"https://www.ecfr.gov/current/title-45/section-87.3","subs":["(d)"],"by":{"2":"28"}},{"t":"reg","label":"81 Fed. Reg. 19,355","url":"https://www.govinfo.gov/link/fr/81/19355","by":{"2":"27"}},{"t":"reg","label":"Exec. Order No. 13,279, 67 Fed. Reg. 77,141","url":"https://www.govinfo.gov/link/fr/67/77141","by":{"2":"27"}},{"t":"reg","label":"Exec. Order No. 14,205, 90 Fed. Reg. 9,499","url":"https://www.govinfo.gov/link/fr/90/9499","by":{"2":"27"}},{"t":"case","label":"Other Authorities Br. for the Fed. Resp’t in Opp’n, Rojas v. Fitch","cite":"1998 WL 34103612","y":1998,"court":"May 20","op":1,"ar":2,"by":{"2":"22"}},{"t":"case","label":"Br. of Baptist Joint Comm. for Religious Liberty, Zubik v. Burwell","cite":"2016 WL 692850","y":2016,"court":"Feb. 17","op":1,"ar":1,"sum":"Noting “political pressure to repeal thousands of narrow religious exemptions already enacted, lest they be expanded to become universal exemptions”.","sumSrc":"brief:2","by":{"2":"45, 47"}},{"t":"case","label":"Reply Br. for Pet’rs, Our Lady of Guadalupe Sch. v. Morrissey-Berru","cite":"2020 WL 1810070","y":2020,"court":"Apr. 3","by":{"2":"30"}},{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"581 U.S. 468","y":2017,"id":"2016/16-74","sc":1,"sum":"The Court determined that the “church plan” exemption of the Employee Retirement Income Security Act of 1974 (ERISA) applies to plans that are maintained by a qualifying church-affiliated organization, even if that organization did not originally establish the plan.","sumSrc":"Oyez","by":{"3":"10-11"}},{"t":"case","label":"Grussgott v. Milwaukee Jewish Day Sch., Inc.","cite":"882 F.3d 655","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/882/655/","by":{"3":"16"}},{"t":"case","label":"Morris Cnty. Bd. of Chosen Freeholders v. Freedom From Religion Found.","cite":"586 U.S. 1213","y":2019,"url":"https://supreme.justia.com/cases/federal/us/586/1213/","sc":1,"by":{"3":"5"}},{"t":"case","label":"Our Lady of Guadalupe Sch. v. MorrisseyBerru","cite":"591 U.S. 732","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/732/","sc":1,"op":3,"by":{"3":"4, 13-14, 15"}},{"t":"case","label":"Shurtleff v. City of Boston","cite":"596 U.S. 243","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/243/","sc":1,"sum":"Rejecting Maine’s anti-establishment argument because a state’s “interest in separating church and state more fiercely than the Federal Constitution cannot qualify as compelling”.","sumSrc":"brief:3","by":{"3":"5-6"}},{"t":"case","label":"Sprietsma v. Mercury Marine","cite":"537 U.S. 51","y":2002,"id":"2002/01-706","sc":1,"sum":"The Court held 8-0 that neither the text nor the intent of the FBSA preempts Sprietsma's common law claims, either explicitly or implicitly.","sumSrc":"Oyez","by":{"3":"7"}},{"t":"usc","label":"29 U.S.C. § 1003","url":"https://www.law.cornell.edu/uscode/text/29/1003","by":{"3":"10"}}]};